import backtrader as bt


class TimeSeriesMomentumStrategy(bt.Strategy):
    params = (
        ("momentum_window", 90),
        ("rebalance_frequency", 21),
        ("target_weight", 0.20),
    )

    def __init__(self):
        lagged_close = self.data.close(-self.p.momentum_window)
        self.momentum = self.data.close / lagged_close - 1.0
        self.average_dollar_volume = bt.indicators.SMA(
            self.data.close * self.data.volume, period=21
        )
        self.momentum_cross = bt.indicators.CrossOver(
            self.data.close, lagged_close
        )
        self.order = None
        self._rebalance_bar = 0
        self._entry_after_close = 0

    def _submit_entry(self, direction):
        allocation = min(self.p.target_weight, 0.10)
        capital = self.broker.getvalue()
        size = allocation * capital / self.data.close[0]
        if direction > 0:
            self.order = self.buy(size=size)
        elif direction < 0:
            self.order = self.sell(size=size)

    def notify_order(self, order):
        if order.status not in (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            return

        was_close = order is self.order and self._entry_after_close != 0
        direction = self._entry_after_close
        self.order = None
        self._entry_after_close = 0

        if was_close and order.status == order.Completed:
            self._submit_entry(direction)

    def next(self):
        is_rebalance = self._rebalance_bar % self.p.rebalance_frequency == 0
        self._rebalance_bar += 1

        if self.order:
            return

        if is_rebalance:
            direction = 0
            liquid = self.average_dollar_volume[0] >= 1_000_000
            enough_history = len(self.data) > self.p.momentum_window
            if liquid and enough_history:
                if self.momentum[0] > 0:
                    direction = 1
                elif self.momentum[0] < 0:
                    direction = -1

            if self.position:
                self._entry_after_close = direction
                self.order = self.close()
            elif direction:
                self._submit_entry(direction)
            return

        if self.position.size > 0 and self.momentum_cross[0] < 0:
            self.order = self.close()
        elif self.position.size < 0 and self.momentum_cross[0] > 0:
            self.order = self.close()
